import { spawn } from "node:child_process";
const UNSAFE_WINDOWS_ARGUMENT = /["%!^&|<>\r\n]/;
function quoteCmd(arg) {
    if (UNSAFE_WINDOWS_ARGUMENT.test(arg)) {
        throw new Error(`unsafe Windows argument: ${arg}`);
    }
    if (arg === "" || /[\t ()]/.test(arg)) {
        return `"${arg}"`;
    }
    return arg;
}
function isErrno(error, code) {
    return (typeof error === "object" &&
        error !== null &&
        "code" in error &&
        error.code === code);
}
export function programTreeKill(pid, platform) {
    if (platform === "win32") {
        return { file: "taskkill", args: ["/pid", String(pid), "/T", "/F"] };
    }
    return { pid: -pid, signal: "SIGTERM" };
}
function killProgramTree(child) {
    const pid = child.pid;
    if (pid === undefined) {
        child.kill("SIGTERM");
        return;
    }
    const plan = programTreeKill(pid, process.platform);
    if ("file" in plan) {
        const killer = spawn(plan.file, [...plan.args], { windowsHide: true, stdio: "ignore" });
        killer.unref();
        killer.once("error", () => {
            child.kill("SIGTERM");
        });
        return;
    }
    try {
        process.kill(plan.pid, plan.signal);
    }
    catch (error) {
        if (isErrno(error, "ESRCH") && !processAlive(pid)) {
            return;
        }
        child.kill("SIGTERM");
    }
}
function processAlive(pid) {
    try {
        process.kill(pid, 0);
        return true;
    }
    catch (error) {
        return !isErrno(error, "ESRCH");
    }
}
function shellRequired(options) {
    const platform = options.platform ?? process.platform;
    return options.windowsShell === true && platform === "win32";
}
export function programExecPlan(command, args, options) {
    if (!shellRequired(options)) {
        return { file: command, args, windowsVerbatimArguments: false };
    }
    // cmd.exe /s strips one outer pair of quotes, so quote the line and wrap it
    // once. cmd.exe passes %% through unchanged, so refuse metacharacters.
    const line = [command, ...args].map((arg) => quoteCmd(arg)).join(" ");
    return {
        file: process.env.ComSpec ?? "cmd.exe",
        args: ["/d", "/s", "/c", `"${line}"`],
        windowsVerbatimArguments: true,
    };
}
export async function runProgram(command, args, options) {
    const plan = programExecPlan(command, args, options);
    return new Promise((resolve, reject) => {
        const { signal } = options;
        if (signal?.aborted === true) {
            reject(abortError(signal));
            return;
        }
        let timedOut = false;
        let settled = false;
        const stdoutChunks = [];
        const stderrChunks = [];
        // On Linux and macOS the program runs detached in its own process group, so
        // Ctrl-C does not reach it. A timeout or an abort kills that whole group,
        // which also ends the Python process under `az`.
        const child = spawn(plan.file, [...plan.args], {
            stdio: ["ignore", "pipe", "pipe"],
            windowsHide: true,
            windowsVerbatimArguments: plan.windowsVerbatimArguments,
            detached: process.platform !== "win32",
        });
        const onAbort = () => {
            killProgramTree(child);
        };
        signal?.addEventListener("abort", onAbort, { once: true });
        child.stdout?.setEncoding("utf8");
        child.stderr?.setEncoding("utf8");
        child.stdout?.on("data", (chunk) => {
            stdoutChunks.push(chunk);
        });
        child.stderr?.on("data", (chunk) => {
            stderrChunks.push(chunk);
        });
        const timer = setTimeout(() => {
            timedOut = true;
            killProgramTree(child);
        }, options.timeoutMs);
        const finish = (error, code) => {
            if (settled) {
                return;
            }
            settled = true;
            clearTimeout(timer);
            signal?.removeEventListener("abort", onAbort);
            const stdout = stdoutChunks.join("");
            const stderr = stderrChunks.join("");
            if (signal?.aborted === true) {
                reject(abortError(signal));
            }
            else if (timedOut) {
                resolve({ code: null, stdout, stderr, timedOut: true });
            }
            else if (error !== undefined) {
                reject(error);
            }
            else if (code === null) {
                reject(new Error(`Command failed: ${plan.file} exited on a signal`));
            }
            else {
                resolve({ code, stdout, stderr, timedOut: false });
            }
        };
        child.once("error", (error) => {
            finish(error, null);
        });
        child.once("close", (code) => {
            finish(undefined, code);
        });
    });
}
function abortError(signal) {
    return Object.assign(new Error("The operation was aborted", { cause: signal.reason }), {
        name: "AbortError",
        code: "ABORT_ERR",
    });
}
